"""Purging the auto-generated files an owner holds, run against a real database."""

from __future__ import annotations

import uuid
from collections.abc import AsyncGenerator

import pytest
import sqlalchemy as sa

from ai.backend.common.data.entity.auto_generated_file import AutoGeneratedFileEntityType
from ai.backend.common.data.entity.domain import DomainID
from ai.backend.common.data.entity.project import ProjectID
from ai.backend.common.data.entity.types import EntityIdentifier
from ai.backend.common.data.entity.user import UserID
from ai.backend.manager.data.auto_generated_file.types import AutoGeneratedFileData
from ai.backend.manager.data.dotfile.types import DotfileEntry
from ai.backend.manager.models.auto_generated_file.creators import AutoGeneratedFileCreator
from ai.backend.manager.models.auto_generated_file.purgers import AutoGeneratedFileBatchPurger
from ai.backend.manager.models.auto_generated_file.row import AutoGeneratedFileRow
from ai.backend.manager.models.auto_generated_file.scopes import AutoGeneratedFileTarget
from ai.backend.manager.models.domain.row import DomainRow
from ai.backend.manager.models.entity_label.row import EntityLabelRow
from ai.backend.manager.models.entity_share.row import EntityShareRow
from ai.backend.manager.models.rbac_models.role.row import RoleRow
from ai.backend.manager.models.resource_policy.row import UserResourcePolicyRow
from ai.backend.manager.models.user.row import UserRow
from ai.backend.manager.models.utils import ExtendedAsyncSAEngine
from ai.backend.manager.models.virtual_entity.entity_membership import EntityMembershipRow
from ai.backend.manager.models.virtual_entity.entity_membership_cap import (
    EntityMembershipCapRow,
)
from ai.backend.manager.models.virtual_entity.entity_membership_field import (
    EntityMembershipFieldRow,
)
from ai.backend.manager.models.virtual_entity.scope_binding import ScopeBindingRow
from ai.backend.manager.models.virtual_entity.virtual_entity import VirtualEntityRow
from ai.backend.manager.repositories.ops.repository import OpsRepository
from ai.backend.manager.repositories.ops.v2.provider import V2DBOpsProvider
from ai.backend.testutils.db import with_tables

_ENTRY = DotfileEntry(path=".bashrc", perm="644", data="")


class TestPurgeOwnedAutoGeneratedFiles:
    @pytest.fixture
    async def db(
        self, database_connection: ExtendedAsyncSAEngine
    ) -> AsyncGenerator[ExtendedAsyncSAEngine, None]:
        async with with_tables(
            database_connection,
            [
                RoleRow,
                VirtualEntityRow,
                EntityMembershipRow,
                EntityMembershipCapRow,
                EntityMembershipFieldRow,
                ScopeBindingRow,
                EntityLabelRow,
                # entity_shares names the sharer in users.
                DomainRow,
                UserResourcePolicyRow,
                UserRow,
                EntityShareRow,
                AutoGeneratedFileRow,
            ],
        ):
            yield database_connection

    async def _file_of(
        self, db: ExtendedAsyncSAEngine, owner: EntityIdentifier
    ) -> AutoGeneratedFileData:
        async with db.begin_session() as session:
            session.add(VirtualEntityRow(entity_type=owner.entity_type(), entity_id=owner))
        ops: OpsRepository[AutoGeneratedFileData] = OpsRepository(V2DBOpsProvider(db))
        return await ops.create_entity(AutoGeneratedFileCreator(owner=owner, entry=_ENTRY))

    @pytest.mark.parametrize(
        "owner",
        [DomainID(uuid.uuid4()), ProjectID(uuid.uuid4()), UserID(uuid.uuid4())],
        ids=["domain", "project", "user"],
    )
    async def test_owners_files_go_with_their_nodes_and_others_stay(
        self, db: ExtendedAsyncSAEngine, owner: EntityIdentifier
    ) -> None:
        owned = await self._file_of(db, owner)
        kept = await self._file_of(db, UserID(uuid.uuid4()))

        async with V2DBOpsProvider(db).write_ops() as w:
            purged = await w.batch_purge_entities_in_scopes(
                [AutoGeneratedFileTarget(owner)], AutoGeneratedFileBatchPurger()
            )

        assert purged == [owned.id]
        async with db.begin_readonly_session() as session:
            rows = (await session.scalars(sa.select(AutoGeneratedFileRow.id))).all()
            nodes = (
                await session.scalars(
                    sa.select(VirtualEntityRow.entity_id).where(
                        VirtualEntityRow.entity_type == AutoGeneratedFileEntityType()
                    )
                )
            ).all()
        assert (rows, nodes) == ([kept.id], [kept.id])
